// Ping every Klyro automation dependency; emit one item per failure.
const checks = [
  ['Klyro API', `${$env.KLYRO_API_BASE}/health`],
  ['Maps scraper', `${$env.SCRAPER_BASE}/api/v1/jobs`],
];
const failures = [];
for (const [name, url] of checks) {
  try {
    const r = await this.helpers.httpRequest({ url, timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    if (r.statusCode !== 200) failures.push(`${name}: HTTP ${r.statusCode}`);
  } catch (e) {
    failures.push(`${name}: ${e.message}`.slice(0, 200));
  }
}
return failures.length ? [{ json: { text: `⚠️ Klyro health check failed\n${failures.join('\n')}` } }] : [];
